   "text": "下面的框線圖顯示某田徑學會的一大群學生完成 100 m 賽跑的所需時間的分佈：\n\n![Q7 框線圖](2012_P1_figs_svg/2012P1_Q7.svg)\n\n該分佈的四分位數間距及分佈域分別為 3.2 s 及 6.8 s。\n\n(a)　求 $a$ 及 $b$。\n\n(b)　該些學生參與某訓練課程。現知在訓練後，該些學生完成 100 m 賽跑的最長所需時間較訓練前少 2.9 s。教練宣稱在訓練後，至少 25% 的學生完成 100 m 賽跑的所需時間有改善。你是否同意？試解釋你的答案。（4 分）",
