   "text": "兩平行線 $L$ 及 $\\ell$ 的 $y$ 截距分別為 $-1$ 及 $-3$，且 $L$ 的 $x$ 截距為 3。$P$ 為直角坐標平面上的一動點使得由 $P$ 至 $L$ 的垂直距離等於由 $P$ 至 $\\ell$ 的垂直距離。將 $P$ 的軌跡記為 $\\Gamma$。\n\n(a)\n\n　　(i)　描述 $\\Gamma$ 與 $L$ 之間的幾何關係。\n\n　　(ii)　求 $\\Gamma$ 的方程。（5 分）\n\n(b)　圓 $C$ 的方程為 $(x-6)^2+y^2=4$。將 $C$ 的圓心記為 $Q$。\n\n　　(i)　$\\Gamma$ 是否通過 $Q$？試解釋你的答案。\n\n　　(ii)　若 $L$ 與 $C$ 相交於 $A$ 及 $B$ 而 $\\Gamma$ 與 $C$ 相交於 $H$ 及 $K$，求 $\\triangle AQH$ 的面積與 $\\triangle BQK$ 的面積之比。（4 分）",
   "html": "<p>14.&nbsp;&nbsp;&nbsp;兩平行線 $L$ 及 $\\ell$ 的 $y$ 截距分別為 $-1$ 及 $-3$，且 $L$ 的 $x$ 截距為 3。$P$ 為直角坐標平面上的一動點使得由 $P$ 至 $L$ 的垂直距離等於由 $P$ 至 $\\ell$ 的垂直距離。將 $P$ 的軌跡記為 $\\Gamma$。</p>\n<p>(a)</p>\n<p>(i)　描述 $\\Gamma$ 與 $L$ 之間的幾何關係。</p>\n<p>(ii)　求 $\\Gamma$ 的方程。（5 分）</p>\n<p>(b)　圓 $C$ 的方程為 $(x-6)^2+y^2=4$。將 $C$ 的圓心記為 $Q$。</p>\n<p>(i)　$\\Gamma$ 是否通過 $Q$？試解釋你的答案。</p>\n<p>(ii)　若 $L$ 與 $C$ 相交於 $A$ 及 $B$ 而 $\\Gamma$ 與 $C$ 相交於 $H$ 及 $K$，求 $\\triangle AQH$ 的面積與 $\\triangle BQK$ 的面積之比。（4 分）</p>",
