   "text": "The figure shows the graph of $ y = a(x + b)^2 $, where $ a $ and $ b $ are constants. Which of the following is true?\n\u0001IMG0\u0001\n\n- A. $ a > 0 $ and $ b > 0 $\n- B. $ a > 0 $ and $ b < 0 $\n- C. $ a < 0 $ and $ b > 0 $\n- D. $ a < 0 $ and $ b < 0 $",
