   "html": "<p>17.&nbsp;&nbsp;&nbsp;In the figure, $B$ is a point lying on $AC$ such that $AB:BC = 3:2$. It is given that $AE \\parallel BD$. If the area of $\\triangle BCD$ and the area of $\\triangle CDE$ are $4 \\text{ cm}^2$ and $8 \\text{ cm}^2$ respectively, then the area of the trapezium $ABDE$ is</p>\n<p><img alt=\"Figure Q17 (as printed)\" src=\"2014P2_figs/Q17.png\" /></p>\n<ul><li>A. $18 \\text{ cm}^2$.</li><li>B. $21 \\text{ cm}^2$.</li><li>C. $27 \\text{ cm}^2$.</li><li>D. $33 \\text{ cm}^2$.</li></ul>",
