   "text": "The stem-and-leaf diagram below shows the distribution of the ages of the passengers in a bus.\n:::stemleaf\nStem (tens) | Leaf (units)\n1 | h 4 6\n2 | 3 3 3 4 6 7 7\n3 | 1 2 2 2 6 8\n4 | 0 k\n:::\nIf the range of the above distribution is at least 33, which of the following must be true?\nI. 0 ≤ h ≤ 3\nII. 3 ≤ k ≤ 9\nIII. 3 ≤ k - h ≤ 5\n\n- A. I only\n- B. II only\n- C. I and III only\n- D. II and III only",
   "html": "<p>30.&nbsp;&nbsp;&nbsp;The stem-and-leaf diagram below shows the distribution of the ages of the passengers in a bus.</p>\n<div class=\"stemleaf\"><div class=\"slcol slL\"><div class=\"slr slh\">Stem (tens)</div><div class=\"slr\">1</div><div class=\"slr\">2</div><div class=\"slr\">3</div><div class=\"slr\">4</div></div><div class=\"slrule\"></div><div class=\"slcol slR\"><div class=\"slr slh\">Leaf (units)</div><div class=\"slr\"><span>h</span><span>4</span><span>6</span></div><div class=\"slr\"><span>3</span><span>3</span><span>3</span><span>4</span><span>6</span><span>7</span><span>7</span></div><div class=\"slr\"><span>1</span><span>2</span><span>2</span><span>2</span><span>6</span><span>8</span></div><div class=\"slr\"><span>0</span><span>k</span></div></div></div>\n<p>If the range of the above distribution is at least 33, which of the following must be true?</p>\n<p>I. 0 ≤ h ≤ 3</p>\n<p>II. 3 ≤ k ≤ 9</p>\n<p>III. 3 ≤ k - h ≤ 5</p>\n<ul><li>A. I only</li><li>B. II only</li><li>C. I and III only</li><li>D. II and III only</li></ul>",
