   "text": "Which of the following are positive statements?\n\n(1) Importation of labour from the mainland would result in a rise in job vacancies in Hong Kong.\n\n(2) It would be better to import labour from the Guangdong province because they can speak Cantonese.\n\n(3) Productivity of labour from China is higher than that from other Southeast Asian countries.\n\n(4) Unemployment rate in Hong Kong would rise by 1% as a result of labour importation of 30 000 from the mainland.\n\n- A. (1) and (2) only\n- B. (3) and (4) only\n- C. (1), (3) and (4) only\n- D. (2), (3) and (4) only",
   "html": "<p>1.&nbsp;&nbsp;&nbsp;Which of the following are positive statements?</p>\n<p>(1) Importation of labour from the mainland would result in a rise in job vacancies in Hong Kong.</p>\n<p>(2) It would be better to import labour from the Guangdong province because they can speak Cantonese.</p>\n<p>(3) Productivity of labour from China is higher than that from other Southeast Asian countries.</p>\n<p>(4) Unemployment rate in Hong Kong would rise by 1% as a result of labour importation of 30 000 from the mainland.</p>\n<ul>\n<li>A. (1) and (2) only</li>\n<li>B. (3) and (4) only</li>\n<li>C. (1), (3) and (4) only</li>\n<li>D. (2), (3) and (4) only</li>\n</ul>",
