   "html": "<p>2.&nbsp;&nbsp;&nbsp;David can choose to take the MTR or a bus to Yuen Long. Suppose the required travel time and the fares of both options are the same in a normal situation. Which of the following will result in an increase in the opportunity cost of travelling to Yuen Long by MTR?</p>\n<ul>\n<li>A. The air-conditioner on the bus is out of order.</li>\n<li>B. The traffic jam makes the bus trip 15 minutes longer.</li>\n<li>C. A signalling problem causes the travel time of the MTR to increase by 15 minutes.</li>\n<li>D. David feels annoyed about the news broadcast in the MTR train.</li>\n</ul>",
