   "text": "Refer to the following table.\n\n| | Factory A | Factory B |\n|---|---|---|\n| Number of full-time workers | 25 | 0 |\n| Number of part-time workers | 0 | 50 |\n| Average working hours of full-time workers | 8 | 0 |\n| Average working hours of part-time workers | 0 | 6 |\n| Total output (units) | 12 000 | 15 000 |\n\nWhich of the following is a possible reason for the difference between the labour productivity of Factory A and Factory B?\n\n- A. Factory A uses time rate while Factory B uses piece rate to pay its workers.\n- B. Factory A provides more training for its workers.\n- C. The part-time workers employed by Factory B are more skilled.\n- D. Factory B uses more capital goods.",
   "html": "<p>6.&nbsp;&nbsp;&nbsp;Refer to the following table.</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>Factory A</th>\n<th>Factory B</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Number of full-time workers</td>\n<td>25</td>\n<td>0</td>\n</tr>\n<tr>\n<td>Number of part-time workers</td>\n<td>0</td>\n<td>50</td>\n</tr>\n<tr>\n<td>Average working hours of full-time workers</td>\n<td>8</td>\n<td>0</td>\n</tr>\n<tr>\n<td>Average working hours of part-time workers</td>\n<td>0</td>\n<td>6</td>\n</tr>\n<tr>\n<td>Total output (units)</td>\n<td>12 000</td>\n<td>15 000</td>\n</tr>\n</tbody>\n</table>\n<p>Which of the following is a possible reason for the difference between the labour productivity of Factory A and Factory B?</p>\n<ul>\n<li>A. Factory A uses time rate while Factory B uses piece rate to pay its workers.</li>\n<li>B. Factory A provides more training for its workers.</li>\n<li>C. The part-time workers employed by Factory B are more skilled.</li>\n<li>D. Factory B uses more capital goods.</li>\n</ul>",
