   "text": "The table below shows the total product of Firm A, which employs only capital and labour in production.\n\n| Labour (units) | Capital (units) | Total Product (units) |\n|---|---|---|\n| 12 | 2 | 110 |\n| 12 | 3 | 130 |\n| 12 | 4 | 160 |\n| 12 | 5 | X |\n\nWhich of the following statements about Firm A is correct?\n\n- A. If the above data illustrate the law of diminishing marginal returns, the value of X can be equal to 180.\n- B. If the above data illustrate the law of diminishing marginal returns, the value of X can be equal to 190.\n- C. If the above data illustrate the law of diminishing marginal returns, the value of X can be larger than 200.\n- D. The law of diminishing marginal returns does not apply to Firm A because capital is not a fixed factor.",
   "html": "<p>9.&nbsp;&nbsp;&nbsp;The table below shows the total product of Firm A, which employs only capital and labour in production.</p>\n<table>\n<thead>\n<tr>\n<th>Labour (units)</th>\n<th>Capital (units)</th>\n<th>Total Product (units)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>12</td>\n<td>2</td>\n<td>110</td>\n</tr>\n<tr>\n<td>12</td>\n<td>3</td>\n<td>130</td>\n</tr>\n<tr>\n<td>12</td>\n<td>4</td>\n<td>160</td>\n</tr>\n<tr>\n<td>12</td>\n<td>5</td>\n<td>X</td>\n</tr>\n</tbody>\n</table>\n<p>Which of the following statements about Firm A is correct?</p>\n<ul>\n<li>A. If the above data illustrate the law of diminishing marginal returns, the value of X can be equal to 180.</li>\n<li>B. If the above data illustrate the law of diminishing marginal returns, the value of X can be equal to 190.</li>\n<li>C. If the above data illustrate the law of diminishing marginal returns, the value of X can be larger than 200.</li>\n<li>D. The law of diminishing marginal returns does not apply to Firm A because capital is not a fixed factor.</li>\n</ul>",
