   "text": "Many people queued up for days for the tickets to watch the show of Tsz-Wah, a famous artist performing stand-up comedy. Some people complained that they were unable to buy tickets even though they were willing to pay the ticket price set by the organiser. The above situation implies that\n\n- A. price was the only criterion for allocating the tickets.\n- B. the producer was not maximising its profit.\n- C. a black market for the tickets might emerge.\n- D. there was an effective price ceiling in the ticket market.",
   "html": "<p>13.&nbsp;&nbsp;&nbsp;Many people queued up for days for the tickets to watch the show of Tsz-Wah, a famous artist performing stand-up comedy. Some people complained that they were unable to buy tickets even though they were willing to pay the ticket price set by the organiser. The above situation implies that</p>\n<ul>\n<li>A. price was the only criterion for allocating the tickets.</li>\n<li>B. the producer was not maximising its profit.</li>\n<li>C. a black market for the tickets might emerge.</li>\n<li>D. there was an effective price ceiling in the ticket market.</li>\n</ul>",
