   "html": "<p>14.&nbsp;&nbsp;&nbsp;Holding other factors constant, a rise in the price of Good X will lead to a fall in the total revenue of Good Y if</p>\n<ul>\n<li>A. Good X and Good Y are complements.</li>\n<li>B. Good X and Good Y are substitutes.</li>\n<li>C. Good X and Good Y are in joint supply.</li>\n<li>D. Good X and Good Y are in competitive supply.</li>\n</ul>",
