   "text": "Refer to the following table for the supply and demand schedules for a good.\n\n| Unit Price (\\$) | 4 | 5 | 6 | 7 | 8 |\n|---|---|---|---|---|---|\n| Quantity demanded (units) | 16 | 14 | 12 | 10 | 8 |\n| Quantity supplied (units) | 14 | 14 | 14 | 14 | 14 |\n\nThe government imposes a \\$2 per unit tax on the good. Which of the following statements about the good is correct?\n\n- A. Sellers' revenue net of tax is \\$70.\n- B. The new market price is \\$6.\n- C. The total tax revenue is \\$28.\n- D. The above information is insufficient to determine the tax burden on sellers.",
   "html": "<p>16.&nbsp;&nbsp;&nbsp;Refer to the following table for the supply and demand schedules for a good.</p>\n<table>\n<thead>\n<tr>\n<th>Unit Price (\\$)</th>\n<th>4</th>\n<th>5</th>\n<th>6</th>\n<th>7</th>\n<th>8</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Quantity demanded (units)</td>\n<td>16</td>\n<td>14</td>\n<td>12</td>\n<td>10</td>\n<td>8</td>\n</tr>\n<tr>\n<td>Quantity supplied (units)</td>\n<td>14</td>\n<td>14</td>\n<td>14</td>\n<td>14</td>\n<td>14</td>\n</tr>\n</tbody>\n</table>\n<p>The government imposes a \\$2 per unit tax on the good. Which of the following statements about the good is correct?</p>\n<ul>\n<li>A. Sellers' revenue net of tax is \\$70.</li>\n<li>B. The new market price is \\$6.</li>\n<li>C. The total tax revenue is \\$28.</li>\n<li>D. The above information is insufficient to determine the tax burden on sellers.</li>\n</ul>",
