   "text": "Which of the following is an example of the divergence between private and social benefits?\n\n- A. A security guard watches live concerts when he is working in a concert hall.\n- B. A tourist enjoys the music performed by a singer on the street and he does not pay for that.\n- C. A resident living next to a karaoke lounge cannot fall asleep because of the noise.\n- D. After the removal of the airport, the market value of the residential flats in that region increases.",
   "html": "<p>17.&nbsp;&nbsp;&nbsp;Which of the following is an example of the divergence between private and social benefits?</p>\n<ul>\n<li>A. A security guard watches live concerts when he is working in a concert hall.</li>\n<li>B. A tourist enjoys the music performed by a singer on the street and he does not pay for that.</li>\n<li>C. A resident living next to a karaoke lounge cannot fall asleep because of the noise.</li>\n<li>D. After the removal of the airport, the market value of the residential flats in that region increases.</li>\n</ul>",
