   "text": "Which of the following is **INCONSISTENT** with the law of demand?\n\n- A. More high-quality Japanese grapes are imported to Hong Kong during Mid-Autumn Festival.\n- B. An increase of the per unit tax on beer results in a fall in the quantity of small-bottle beer sold in the market.\n- C. After the introduction of the airport departure tax which is a fixed amount for any traveller, the average length of airplane journeys decreases.\n- D. The birth rate increases when the income tax allowance for children increases.",
   "html": "<p>18.&nbsp;&nbsp;&nbsp;Which of the following is <strong>INCONSISTENT</strong> with the law of demand?</p>\n<ul>\n<li>A. More high-quality Japanese grapes are imported to Hong Kong during Mid-Autumn Festival.</li>\n<li>B. An increase of the per unit tax on beer results in a fall in the quantity of small-bottle beer sold in the market.</li>\n<li>C. After the introduction of the airport departure tax which is a fixed amount for any traveller, the average length of airplane journeys decreases.</li>\n<li>D. The birth rate increases when the income tax allowance for children increases.</li>\n</ul>",
