   "text": "Which of the following statements about the theme park industry in Hong Kong is correct?\n\n- A. Hong Kong Disneyland is a monopolist because its average cost of production drops when there are more tourists.\n- B. Hong Kong Disneyland guarantees a profit because it is protected by the government.\n- C. Hong Kong Disneyland and Ocean Park Hong Kong have no competition with each other as tourists may go to both theme parks.\n- D. Hong Kong Disneyland and Ocean Park Hong Kong are interdependent in their marketing strategies.",
   "html": "<p>20.&nbsp;&nbsp;&nbsp;Which of the following statements about the theme park industry in Hong Kong is correct?</p>\n<ul>\n<li>A. Hong Kong Disneyland is a monopolist because its average cost of production drops when there are more tourists.</li>\n<li>B. Hong Kong Disneyland guarantees a profit because it is protected by the government.</li>\n<li>C. Hong Kong Disneyland and Ocean Park Hong Kong have no competition with each other as tourists may go to both theme parks.</li>\n<li>D. Hong Kong Disneyland and Ocean Park Hong Kong are interdependent in their marketing strategies.</li>\n</ul>",
