   "text": "Refer to the following diagram.\n\n![fig_2015P1_q22](2015_P1_images/fig_2015P1_q22.png)\n\nThe maximum total social surplus is equal to \\_\\_\\_\\_\\_\\_\\_\\_\\_\\_.\n\n- A. area Z\n- B. area $(Y+Z)$\n- C. area $(W+X+Y)$\n- D. area $(X+Y+Z)$",
