   "text": "The following table shows the employment distribution in an economy.\n\n| Sector \\ Year | 2010 | 2014 |\n|---|---|---|\n| Primary | 0.4% | 0.4% |\n| Secondary | 23.6% | 18.5% |\n| Tertiary | 76.0% | 81.1% |\n| Total | 100% | 100% |\n\nFrom the above table, we can conclude that from 2010 to 2014,\n\n- A. the number of workers engaged in the primary sector remained constant.\n- B. the overall employment rate was the same.\n- C. the contribution of the tertiary sector to gross domestic product (GDP) increased.\n- D. the relative importance of the secondary sector in terms of employment decreased.",
   "html": "<p>23.&nbsp;&nbsp;&nbsp;The following table shows the employment distribution in an economy.</p>\n<table>\n<thead>\n<tr>\n<th>Sector \\ Year</th>\n<th>2010</th>\n<th>2014</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Primary</td>\n<td>0.4%</td>\n<td>0.4%</td>\n</tr>\n<tr>\n<td>Secondary</td>\n<td>23.6%</td>\n<td>18.5%</td>\n</tr>\n<tr>\n<td>Tertiary</td>\n<td>76.0%</td>\n<td>81.1%</td>\n</tr>\n<tr>\n<td>Total</td>\n<td>100%</td>\n<td>100%</td>\n</tr>\n</tbody>\n</table>\n<p>From the above table, we can conclude that from 2010 to 2014,</p>\n<ul>\n<li>A. the number of workers engaged in the primary sector remained constant.</li>\n<li>B. the overall employment rate was the same.</li>\n<li>C. the contribution of the tertiary sector to gross domestic product (GDP) increased.</li>\n<li>D. the relative importance of the secondary sector in terms of employment decreased.</li>\n</ul>",
