   "text": "Refer to the following table about an economy.\n\n<table>\n<tr><th></th><th colspan=\"2\">Growth rate (relative to previous year) (%)</th></tr>\n<tr><th></th><th>Year 1</th><th>Year 2</th></tr>\n<tr><td>Nominal GDP</td><td>4</td><td>0</td></tr>\n<tr><td>General price level</td><td>3</td><td>1</td></tr>\n<tr><td>Population</td><td>−1</td><td>2</td></tr>\n</table>\n\nWhich of the following statements about the economy is correct?\n\n- A. The per capita nominal GDP in year 2 is the same as that in year 1.\n- B. The real output increased in year 2.\n- C. The general price level decreased in year 2.\n- D. The per capita real GDP decreased in year 2.",
   "html": "<p>25.&nbsp;&nbsp;&nbsp;Refer to the following table about an economy.</p>\n<table>\n<tr><th></th><th colspan=\"2\">Growth rate (relative to previous year) (%)</th></tr>\n<tr><th></th><th>Year 1</th><th>Year 2</th></tr>\n<tr><td>Nominal GDP</td><td>4</td><td>0</td></tr>\n<tr><td>General price level</td><td>3</td><td>1</td></tr>\n<tr><td>Population</td><td>−1</td><td>2</td></tr>\n</table>\n\n<p>Which of the following statements about the economy is correct?</p>\n<ul>\n<li>A. The per capita nominal GDP in year 2 is the same as that in year 1.</li>\n<li>B. The real output increased in year 2.</li>\n<li>C. The general price level decreased in year 2.</li>\n<li>D. The per capita real GDP decreased in year 2.</li>\n</ul>",
