   "text": "Which of the following transactions would increase the money supply (M2) of Hong Kong?\n\n- A. Ms Chan transfers \\$500 000 from her time deposit account in a restricted licence bank to her time deposit account in a licensed bank.\n- B. Mr Lee transfers \\$200 000 from his current account to his savings account in a licensed bank.\n- C. Mr Man deposits \\$100 000 cash into his savings account in a licensed bank.\n- D. Ms Chung deposits \\$600 000 cash into her time deposit account in a deposit-taking company.",
   "html": "<p>30.&nbsp;&nbsp;&nbsp;Which of the following transactions would increase the money supply (M2) of Hong Kong?</p>\n<ul>\n<li>A. Ms Chan transfers \\$500 000 from her time deposit account in a restricted licence bank to her time deposit account in a licensed bank.</li>\n<li>B. Mr Lee transfers \\$200 000 from his current account to his savings account in a licensed bank.</li>\n<li>C. Mr Man deposits \\$100 000 cash into his savings account in a licensed bank.</li>\n<li>D. Ms Chung deposits \\$600 000 cash into her time deposit account in a deposit-taking company.</li>\n</ul>",
