   "text": "Refer to the following news extract.\n\n> Yu'e Bao（餘額寶）is a new online investment fund introduced by Alibaba. Much of the popularity of Yu'e Bao has come from its ability to give customers the convenience of a demand deposit—meaning they can withdraw their funds whenever they like—but with returns well above what a bank could offer. It recently advertised an annualised return of 5.25%, but that level has on occasion risen to above 7% since the fund was set up. By contrast, banks offer 3.3% as interest for a one-year fixed deposit and close to nothing on savings deposits.\n\nYu'e Bao is a better \\_\\_\\_\\_\\_\\_\\_\\_\\_\\_ as compared with bank deposits because \\_\\_\\_\\_\\_\\_\\_\\_\\_\\_.\n\n- A. unit of account ...... it provides a homogeneous means of payment\n- B. unit of account ...... it can facilitate people's buying and selling of goods and services\n- C. store of value ...... it allows customers to have higher purchasing power in the future\n- D. store of value ...... the customers can keep their unused funds in Yu'e Bao",
   "html": "<p>35.&nbsp;&nbsp;&nbsp;Refer to the following news extract.</p>\n<blockquote>\n<p>Yu'e Bao（餘額寶）is a new online investment fund introduced by Alibaba. Much of the popularity of Yu'e Bao has come from its ability to give customers the convenience of a demand deposit—meaning they can withdraw their funds whenever they like—but with returns well above what a bank could offer. It recently advertised an annualised return of 5.25%, but that level has on occasion risen to above 7% since the fund was set up. By contrast, banks offer 3.3% as interest for a one-year fixed deposit and close to nothing on savings deposits.</p>\n</blockquote>\n<p>Yu'e Bao is a better __________ as compared with bank deposits because __________.</p>\n<ul>\n<li>A. unit of account ...... it provides a homogeneous means of payment</li>\n<li>B. unit of account ...... it can facilitate people's buying and selling of goods and services</li>\n<li>C. store of value ...... it allows customers to have higher purchasing power in the future</li>\n<li>D. store of value ...... the customers can keep their unused funds in Yu'e Bao</li>\n</ul>",
