   "text": "The stem-and-leaf diagram below shows the distribution of the scores (in marks) of a group of students in a test. Ada gets the highest score in the test.\n:::stemleaf\nStem (tens) | Leaf (units)\n4 | 5 6 7 8\n5 | 5 5 6 8\n6 | 3 5 5 6 9 9\n7 | 0 0 1\n8 | 0 2 5\n:::\nWhich of the following is/are true?\nI. The upper quartile of the distribution is 55 marks.\nII. The standard score of Ada in the test is lower than 2.\nIII. The standard deviation of the distribution is greater than 12 marks.\n\n- A. I only\n- B. II only\n- C. I and III only\n- D. II and III only",
   "html": "<p>44.&nbsp;&nbsp;&nbsp;The stem-and-leaf diagram below shows the distribution of the scores (in marks) of a group of students in a test. Ada gets the highest score in the test.</p>\n<div class=\"stemleaf\"><div class=\"slcol slL\"><div class=\"slr slh\">Stem (tens)</div><div class=\"slr\">4</div><div class=\"slr\">5</div><div class=\"slr\">6</div><div class=\"slr\">7</div><div class=\"slr\">8</div></div><div class=\"slrule\"></div><div class=\"slcol slR\"><div class=\"slr slh\">Leaf (units)</div><div class=\"slr\"><span>5</span><span>6</span><span>7</span><span>8</span></div><div class=\"slr\"><span>5</span><span>5</span><span>6</span><span>8</span></div><div class=\"slr\"><span>3</span><span>5</span><span>5</span><span>6</span><span>9</span><span>9</span></div><div class=\"slr\"><span>0</span><span>0</span><span>1</span></div><div class=\"slr\"><span>0</span><span>2</span><span>5</span></div></div></div>\n<p>Which of the following is/are true?</p>\n<p>I. The upper quartile of the distribution is 55 marks.</p>\n<p>II. The standard score of Ada in the test is lower than 2.</p>\n<p>III. The standard deviation of the distribution is greater than 12 marks.</p>\n<ul><li>A. I only</li><li>B. II only</li><li>C. I and III only</li><li>D. II and III only</li></ul>",
