   "text": "The government launched the Silver Bond for Hong Kong residents aged 65 or above. Bondholders will be paid interest at a rate linked to inflation in Hong Kong, subject to a minimum rate of 2% per year. Bondholders may sell their bonds at original price to the government before maturity.\n\nWhich of the following statements about the Silver Bond is/are correct?\n(1) The risk of holding the Silver Bond is lower than that of the shares of a listed company.\n(2) The return of the Silver Bond would increase during inflation while the return of the shares of a listed company would not.\n(3) The interest received by Silver Bond holders is higher than the dividend received by the shareholders of a listed company.\n\n- A. (1) only\n- B. (2) only\n- C. (3) only\n- D. (1), (2) and (3)",
   "html": "<p>6.&nbsp;&nbsp;&nbsp;The government launched the Silver Bond for Hong Kong residents aged 65 or above. Bondholders will be paid interest at a rate linked to inflation in Hong Kong, subject to a minimum rate of 2% per year. Bondholders may sell their bonds at original price to the government before maturity.</p>\n<p>Which of the following statements about the Silver Bond is/are correct?\n(1) The risk of holding the Silver Bond is lower than that of the shares of a listed company.\n(2) The return of the Silver Bond would increase during inflation while the return of the shares of a listed company would not.\n(3) The interest received by Silver Bond holders is higher than the dividend received by the shareholders of a listed company.</p>\n<ul>\n<li>A. (1) only</li>\n<li>B. (2) only</li>\n<li>C. (3) only</li>\n<li>D. (1), (2) and (3)</li>\n</ul>",
