   "text": "The following table shows the cost-output relationship of a price-taker.\n\n| Output (units) | Average cost ($) |\n|---|---|\n| 5 | 10 |\n| 6 | 11 |\n| 7 | 12 |\n| 8 | 13 |\n| 9 | 14 |\n\nThe market price is \\$20. Suppose the average cost has increased by \\$2 for every unit of output. The profit of the firm will \\_\\_\\_\\_\\_\\_.\n\n- A. increase by \\$16\n- B. increase by \\$14\n- C. decrease by \\$16\n- D. decrease by \\$14",
   "html": "<p>8.&nbsp;&nbsp;&nbsp;The following table shows the cost-output relationship of a price-taker.</p>\n<table>\n<thead>\n<tr>\n<th>Output (units)</th>\n<th>Average cost ($)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>5</td>\n<td>10</td>\n</tr>\n<tr>\n<td>6</td>\n<td>11</td>\n</tr>\n<tr>\n<td>7</td>\n<td>12</td>\n</tr>\n<tr>\n<td>8</td>\n<td>13</td>\n</tr>\n<tr>\n<td>9</td>\n<td>14</td>\n</tr>\n</tbody>\n</table>\n<p>The market price is \\$20. Suppose the average cost has increased by \\$2 for every unit of output. The profit of the firm will ______.</p>\n<ul>\n<li>A. increase by \\$16</li>\n<li>B. increase by \\$14</li>\n<li>C. decrease by \\$16</li>\n<li>D. decrease by \\$14</li>\n</ul>",
