   "text": "A famous artist, Tsz-Wah, held a show. Many people complained that they could not buy a ticket. Ticket touts resold the tickets on the Internet and some buyers paid a price higher than HK\\$10 000 for a ticket.\n\nThe above case illustrates the \\_\\_\\_\\_\\_\\_ function of price because \\_\\_\\_\\_\\_\\_.\n\n- A. rationing ...... the tickets are rationed to the highest-valued buyers\n- B. rationing ...... demand will be reduced by a higher price\n- C. allocative ...... more profits can be earned with a higher price\n- D. allocative ...... more resources should be allocated to the producer to raise the supply",
   "html": "<p>12.&nbsp;&nbsp;&nbsp;A famous artist, Tsz-Wah, held a show. Many people complained that they could not buy a ticket. Ticket touts resold the tickets on the Internet and some buyers paid a price higher than HK\\$10 000 for a ticket.</p>\n<p>The above case illustrates the ______ function of price because ______.</p>\n<ul>\n<li>A. rationing ...... the tickets are rationed to the highest-valued buyers</li>\n<li>B. rationing ...... demand will be reduced by a higher price</li>\n<li>C. allocative ...... more profits can be earned with a higher price</li>\n<li>D. allocative ...... more resources should be allocated to the producer to raise the supply</li>\n</ul>",
