   "text": "Which of the following is **INCONSISTENT** with the law of demand?\n\n- A. The abolishment of per unit import tariff on garment results in a rise in the quality of imported garments.\n- B. Live fishes sold in a market near the fish farm have a higher price than frozen fishes sold in a faraway market.\n- C. The ratio of high-quality white wine sold to total white wine sold remains unchanged when the government imposes an ad valorem tax on white wine.\n- D. Developers tend to build higher-quality housing units on a piece of land with a good view.",
   "html": "<p>13.&nbsp;&nbsp;&nbsp;Which of the following is <strong>INCONSISTENT</strong> with the law of demand?</p>\n<ul>\n<li>A. The abolishment of per unit import tariff on garment results in a rise in the quality of imported garments.</li>\n<li>B. Live fishes sold in a market near the fish farm have a higher price than frozen fishes sold in a faraway market.</li>\n<li>C. The ratio of high-quality white wine sold to total white wine sold remains unchanged when the government imposes an ad valorem tax on white wine.</li>\n<li>D. Developers tend to build higher-quality housing units on a piece of land with a good view.</li>\n</ul>",
