   "text": "Refer to the following conversation between Mandy and Shirley.\n\nMandy: I like coffee very much! No matter how its price changes, I always buy the same amount of coffee every week!\n\nShirley: I like coffee very much too! No matter how its price changes, I always spend the same amount of money on coffee every week!\n\nBased on their conversation, Mandy’s demand for coffee is \\_\\_\\_\\_\\_\\_ and Shirley’s demand for coffee is \\_\\_\\_\\_\\_\\_.\n\n- A. perfectly inelastic ...... perfectly inelastic\n- B. perfectly inelastic ...... unitarily elastic\n- C. unitarily elastic ...... perfectly inelastic\n- D. unitarily elastic ...... unitarily elastic",
   "html": "<p>15.&nbsp;&nbsp;&nbsp;Refer to the following conversation between Mandy and Shirley.</p>\n<p>Mandy: I like coffee very much! No matter how its price changes, I always buy the same amount of coffee every week!</p>\n<p>Shirley: I like coffee very much too! No matter how its price changes, I always spend the same amount of money on coffee every week!</p>\n<p>Based on their conversation, Mandy’s demand for coffee is ______ and Shirley’s demand for coffee is ______.</p>\n<ul>\n<li>A. perfectly inelastic ...... perfectly inelastic</li>\n<li>B. perfectly inelastic ...... unitarily elastic</li>\n<li>C. unitarily elastic ...... perfectly inelastic</li>\n<li>D. unitarily elastic ...... unitarily elastic</li>\n</ul>",
