   "text": "Refer to the following supply and demand schedules for Good X.\n\n| Unit price ($) | 6 | 7 | 8 | 9 | 10 | 11 | 12 | 13 |\n|---|---|---|---|---|---|---|---|---|\n| Quantity demanded | 140 | 130 | 120 | 110 | 100 | 90 | 80 | 70 |\n| Quantity supplied | 60 | 70 | 80 | 90 | 100 | 110 | 120 | 130 |\n\nIf the government imposed a \\$2 per unit tax on Good X,\n\n- A. sellers’ revenue net of tax would become \\$990.\n- B. tax burden borne by the sellers would be \\$90.\n- C. the total tax revenue would be \\$200.\n- D. buyers’ total expenditure on Good X would decrease by \\$40.",
   "html": "<p>16.&nbsp;&nbsp;&nbsp;Refer to the following supply and demand schedules for Good X.</p>\n<table>\n<thead>\n<tr>\n<th>Unit price ($)</th>\n<th>6</th>\n<th>7</th>\n<th>8</th>\n<th>9</th>\n<th>10</th>\n<th>11</th>\n<th>12</th>\n<th>13</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Quantity demanded</td>\n<td>140</td>\n<td>130</td>\n<td>120</td>\n<td>110</td>\n<td>100</td>\n<td>90</td>\n<td>80</td>\n<td>70</td>\n</tr>\n<tr>\n<td>Quantity supplied</td>\n<td>60</td>\n<td>70</td>\n<td>80</td>\n<td>90</td>\n<td>100</td>\n<td>110</td>\n<td>120</td>\n<td>130</td>\n</tr>\n</tbody>\n</table>\n<p>If the government imposed a \\$2 per unit tax on Good X,</p>\n<ul>\n<li>A. sellers’ revenue net of tax would become \\$990.</li>\n<li>B. tax burden borne by the sellers would be \\$90.</li>\n<li>C. the total tax revenue would be \\$200.</li>\n<li>D. buyers’ total expenditure on Good X would decrease by \\$40.</li>\n</ul>",
