   "html": "<p>20.&nbsp;&nbsp;&nbsp;Li Ka Shing Foundation gave HK\\$5 000 to each 2017 HKDSE candidate living in those remote districts with lower average household income. Which of the following statements about this unconditional gift is correct?</p>\n<ul>\n<li>A. It reduces the income inequality as a larger portion of the receivers of the gift are from lower income group.</li>\n<li>B. It increases the income inequality as it is unfair to the candidates living in the non-remote districts.</li>\n<li>C. As the money is given to all candidates living in those remote districts, income distribution remains unchanged.</li>\n<li>D. It helps equalising opportunities as those candidates will study harder to improve their exam results.</li>\n</ul>",
