   "html": "<p>22.&nbsp;&nbsp;&nbsp;The Work Incentive Transport Subsidy Scheme helps low-income earners reduce their cost of travelling to and from work and encourages them to get a job. Workers meeting certain criteria, such as monthly income and asset limits, are eligible to get the subsidy.</p>\n<p>Which of the following would likely occur after the implementation of this scheme?\n(1) Labour supply would increase.\n(2) Labour productivity would increase.\n(3) Geographical mobility of labour would increase.\n(4) Income inequality would decrease.</p>\n<ul>\n<li>A. (1) and (2) only</li>\n<li>B. (3) and (4) only</li>\n<li>C. (1), (3) and (4) only</li>\n<li>D. (2), (3) and (4) only</li>\n</ul>",
