   "html": "<p>36.&nbsp;&nbsp;&nbsp;According to the quantity theory of money, if a central bank increases money supply,</p>\n<ul>\n<li>A. the price level will increase.</li>\n<li>B. real output will remain constant.</li>\n<li>C. nominal output will increase.</li>\n<li>D. the unemployment rate will decrease.</li>\n</ul>",
