   "text": "Which of the following policies would most likely lead to a drop in aggregate output?\n\n- A. The government bought bonds from the public and raised the tax allowance at the same time.\n- B. The government sold bonds to the public and reduced transfer payment to the poor at the same time.\n- C. The government reduced required reserve ratio and raised the progressivity of income tax at the same time.\n- D. The government increased the discount rate and lowered profits tax rate at the same time.",
   "html": "<p>37.&nbsp;&nbsp;&nbsp;Which of the following policies would most likely lead to a drop in aggregate output?</p>\n<ul>\n<li>A. The government bought bonds from the public and raised the tax allowance at the same time.</li>\n<li>B. The government sold bonds to the public and reduced transfer payment to the poor at the same time.</li>\n<li>C. The government reduced required reserve ratio and raised the progressivity of income tax at the same time.</li>\n<li>D. The government increased the discount rate and lowered profits tax rate at the same time.</li>\n</ul>",
