   "text": "To reduce fiscal deficits, the government may adopt either contractionary fiscal policy (e.g. increase taxes and/or decrease fiscal spending) or expansionary monetary policy (e.g. finance the deficits by printing money).\n\nRefer to a situation of an upward-sloping short run aggregate supply curve. Which of the following are the advantages of using expansionary monetary policy over contractionary fiscal policy to reduce fiscal deficits?\n(1) The employment level will be higher.\n(2) The purchasing power of money will be higher.\n(3) The real output level will be higher.\n\n- A. (1) and (2) only\n- B. (1) and (3) only\n- C. (2) and (3) only\n- D. (1), (2) and (3)",
   "html": "<p>38.&nbsp;&nbsp;&nbsp;To reduce fiscal deficits, the government may adopt either contractionary fiscal policy (e.g. increase taxes and/or decrease fiscal spending) or expansionary monetary policy (e.g. finance the deficits by printing money).</p>\n<p>Refer to a situation of an upward-sloping short run aggregate supply curve. Which of the following are the advantages of using expansionary monetary policy over contractionary fiscal policy to reduce fiscal deficits?\n(1) The employment level will be higher.\n(2) The purchasing power of money will be higher.\n(3) The real output level will be higher.</p>\n<ul>\n<li>A. (1) and (2) only</li>\n<li>B. (1) and (3) only</li>\n<li>C. (2) and (3) only</li>\n<li>D. (1), (2) and (3)</li>\n</ul>",
   "file": "2017_P1_QU(ENG).md"
