   "text": "The diagram below shows the aggregate demand curve, the short run aggregate supply curve and the long run aggregate supply curve of an economy.\n\n\nSuppose the economy initially operates at $E_1$ and the total import value equals total export value. If the government decreases the social security assistance to the elderly, in short run, the deflationary (output) gap will be \\_\\_\\_\\_\\_\\_ and there will be a \\_\\_\\_\\_\\_\\_.\n\n- A. narrower ...... trade surplus\n- B. wider ...... trade deficit\n- C. narrower ...... trade deficit\n- D. wider ...... trade surplus",
   "html": "<p>39.&nbsp;&nbsp;&nbsp;The diagram below shows the aggregate demand curve, the short run aggregate supply curve and the long run aggregate supply curve of an economy.</p>\n<p>Suppose the economy initially operates at $E_1$ and the total import value equals total export value. If the government decreases the social security assistance to the elderly, in short run, the deflationary (output) gap will be ______ and there will be a ______.</p>\n<ul>\n<li>A. narrower ...... trade surplus</li>\n<li>B. wider ...... trade deficit</li>\n<li>C. narrower ...... trade deficit</li>\n<li>D. wider ...... trade surplus</li>\n</ul>",
