   "html": "<p>44.&nbsp;&nbsp;&nbsp;44</p>\n<table>\n<thead>\n<tr>\n<th>Date</th>\n<th>Exchange rates</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>22 November 2015</td>\n<td>US\\$1 = RMB¥6.39</td>\n</tr>\n<tr>\n<td>22 November 2016</td>\n<td>US\\$1 = RMB¥6.89</td>\n</tr>\n</tbody>\n</table>\n<p>The above change in the exchange rate between the US Dollar and the Renminbi would lead to\n(1) a decrease in the number of Chinese tourists to the US.\n(2) a decrease in the competitiveness of US exports to China.\n(3) an increase in the total value of US exports to China (in terms of the US Dollar).</p>\n<ul>\n<li>A. (1) and (2) only</li>\n<li>B. (1) and (3) only</li>\n<li>C. (2) and (3) only</li>\n<li>D. (1), (2) and (3)</li>\n</ul>",
