   "text": "A car travels from city $P$ to city $Q$ at an average speed of $72\\text{ km}/\\text{h}$ and then the car travels from city $Q$ to city $R$ at an average speed of $90\\text{ km}/\\text{h}$ . It is given that the car travels $210\\text{ km}$ in $161$ minutes for the whole journey. How long does the car take to travel from city $P$ to city $Q$ ?  (5 marks)",
