   "text": "The box-and-whisker diagram below shows the distribution of the ages of the clerks in team $X$ of a company. It is given that the range and the inter-quartile range of this distribution are $43$ and $21$ respectively.\n(a) Find $a$ and $b$ .\n(3 marks)\n(b) There are five clerks in team $Y$ of the company and three of them are of age $38$ . It is given that the range of the ages of the clerks in team $Y$ is $20$ . Team $X$ and team $Y$ are now combined to form a section. The manager of the company claims that the range of the ages of the clerks in the section and the range of the ages of the clerks in team $X$ must be the same. Do you agree? Explain your answer.\n(2 marks)\n\n![figure](2018P1_figs_svg/Fig2.png)",
   "html": "<p>10.&nbsp;&nbsp;&nbsp;The box-and-whisker diagram below shows the distribution of the ages of the clerks in team $X$ of a company. It is given that the range and the inter-quartile range of this distribution are $43$ and $21$ respectively.\n(a) Find $a$ and $b$ .\n(3 marks)\n(b) There are five clerks in team $Y$ of the company and three of them are of age $38$ . It is given that the range of the ages of the clerks in team $Y$ is $20$ . Team $X$ and team $Y$ are now combined to form a section. The manager of the company claims that the range of the ages of the clerks in the section and the range of the ages of the clerks in team $X$ must be the same. Do you agree? Explain your answer.\n(2 marks)</p>\n<p><img alt=\"figure\" src=\"2018P1_figs_svg/Fig2.png\" /></p>",
