   "text": "In Figure 2, $ABCD$ is a trapezium with $\\angle ABC=90^{\\circ}$ and $AB \\parallel DC$ . $E$ is a point lying on $BC$ such that $\\angle AED=90^{\\circ}$ .\n(a) Prove that $\\triangle ABE \\sim \\triangle ECD$ .\n(2 marks)\n(b) It is given that $AB=15\\text{ cm}$ , $AE=25\\text{ cm}$ and $CE=36\\text{ cm}$ .\n(i) Find the length of $CD$ .\n(ii) Find the area of $\\triangle ADE$ .\n(iii) Is there a point $F$ lying on $AD$ such that the distance between $E$ and $F$ is less than $23\\text{ cm}$ ? Explain your answer.\n(6 marks)\n\n![Figure 2](2018P1_figs_svg/Fig3.png)",
   "html": "<p>13.&nbsp;&nbsp;&nbsp;In Figure 2, $ABCD$ is a trapezium with $\\angle ABC=90^{\\circ}$ and $AB \\parallel DC$ . $E$ is a point lying on $BC$ such that $\\angle AED=90^{\\circ}$ .\n(a) Prove that $\\triangle ABE \\sim \\triangle ECD$ .\n(2 marks)\n(b) It is given that $AB=15\\text{ cm}$ , $AE=25\\text{ cm}$ and $CE=36\\text{ cm}$ .\n(i) Find the length of $CD$ .\n(ii) Find the area of $\\triangle ADE$ .\n(iii) Is there a point $F$ lying on $AD$ such that the distance between $E$ and $F$ is less than $23\\text{ cm}$ ? Explain your answer.\n(6 marks)</p>\n<p><img alt=\"Figure 2\" src=\"2018P1_figs_svg/Fig3.png\" /></p>",
