   "text": "A right circular cylindrical container of base radius $8\\text{ cm}$ and height $64\\text{ cm}$ and an inverted right circular conical vessel of base radius $20\\text{ cm}$ and height $60\\text{ cm}$ are held vertically. The container is fully filled with water. The water in the container is now poured into the vessel.\n(a) Find the volume of water in the vessel in terms of $\\pi$ .\n(2 marks)\n(b) Find the depth of water in the vessel.\n(4 marks)\n(c) If a solid metal sphere of radius $14\\text{ cm}$ is then put into the vessel and the sphere is totally immersed in the water, will the water overflow? Explain your answer.\n(3 marks)",
   "html": "<p>14.&nbsp;&nbsp;&nbsp;A right circular cylindrical container of base radius $8\\text{ cm}$ and height $64\\text{ cm}$ and an inverted right circular conical vessel of base radius $20\\text{ cm}$ and height $60\\text{ cm}$ are held vertically. The container is fully filled with water. The water in the container is now poured into the vessel.\n(a) Find the volume of water in the vessel in terms of $\\pi$ .\n(2 marks)\n(b) Find the depth of water in the vessel.\n(4 marks)\n(c) If a solid metal sphere of radius $14\\text{ cm}$ is then put into the vessel and the sphere is totally immersed in the water, will the water overflow? Explain your answer.\n(3 marks)</p>",
