   "text": "It is given that $\\mathrm{f}(x)$ partly varies as $x^{2}$ and partly varies as $x$ . Suppose that $\\mathrm{f}(2)=60$ and $\\mathrm{f}(3)=99$ .\n(a) Find $\\mathrm{f}(x)$ .\n(3 marks)\n(b) Let $Q$ be the vertex of the graph of $y=\\mathrm{f}(x)$ and $R$ be the vertex of the graph of $y=27-\\mathrm{f}(x)$ .\n(i) Using the method of completing the square, find the coordinates of $Q$ .\n(ii) Write down the coordinates of $R$ .\n(iii) The coordinates of the point $S$ are $(56,0)$ . Let $P$ be the circumcentre of $\\Delta QRS$ . Describe the geometric relationship between $P$ , $Q$ and $R$ . Explain your answer.\n(5 marks)",
   "html": "<p>18.&nbsp;&nbsp;&nbsp;It is given that $\\mathrm{f}(x)$ partly varies as $x^{2}$ and partly varies as $x$ . Suppose that $\\mathrm{f}(2)=60$ and $\\mathrm{f}(3)=99$ .\n(a) Find $\\mathrm{f}(x)$ .\n(3 marks)\n(b) Let $Q$ be the vertex of the graph of $y=\\mathrm{f}(x)$ and $R$ be the vertex of the graph of $y=27-\\mathrm{f}(x)$ .\n(i) Using the method of completing the square, find the coordinates of $Q$ .\n(ii) Write down the coordinates of $R$ .\n(iii) The coordinates of the point $S$ are $(56,0)$ . Let $P$ be the circumcentre of $\\Delta QRS$ . Describe the geometric relationship between $P$ , $Q$ and $R$ . Explain your answer.\n(5 marks)</p>",
