   "text": "Tai On Building（太安樓）in eastern Hong Kong Island is well-known as a 'foodie paradise'. A variety of street snacks such as cart noodles, egg waffles, dumplings and mango mochi are sold by numerous small vendors. Customers from different districts fill their stomachs at Tai On Building.\n\nBased on the above information, street snack vendors at Tai On Building can \\_\\_\\_\\_\\_\\_.\n\n- A. enjoy internal economies of scale\n- B. enjoy external economies of scale\n- C. suffer internal diseconomies of scale\n- D. suffer external diseconomies of scale",
   "html": "<p>7.&nbsp;&nbsp;&nbsp;Tai On Building（太安樓）in eastern Hong Kong Island is well-known as a 'foodie paradise'. A variety of street snacks such as cart noodles, egg waffles, dumplings and mango mochi are sold by numerous small vendors. Customers from different districts fill their stomachs at Tai On Building.</p>\n<p>Based on the above information, street snack vendors at Tai On Building can ______.</p>\n<ul>\n<li>A. enjoy internal economies of scale</li>\n<li>B. enjoy external economies of scale</li>\n<li>C. suffer internal diseconomies of scale</li>\n<li>D. suffer external diseconomies of scale</li>\n</ul>",
