   "text": "In recent years, the rise in demand for private cars in China has attracted Volkswagen, a German car manufacturer, to set up car manufacturing factories in China.\n\nThe above case illustrates the \\_\\_\\_\\_\\_\\_ function of price because \\_\\_\\_\\_\\_\\_.\n\n- A. rationing ...... private cars are sold to the highest-valued users in China\n- B. rationing ...... fewer buyers are willing to buy private cars in Germany\n- C. allocative ...... the supply of private cars falls in Germany\n- D. allocative ...... more resources are allocated to the production of private cars in China",
   "html": "<p>13.&nbsp;&nbsp;&nbsp;In recent years, the rise in demand for private cars in China has attracted Volkswagen, a German car manufacturer, to set up car manufacturing factories in China.</p>\n<p>The above case illustrates the ______ function of price because ______.</p>\n<ul>\n<li>A. rationing ...... private cars are sold to the highest-valued users in China</li>\n<li>B. rationing ...... fewer buyers are willing to buy private cars in Germany</li>\n<li>C. allocative ...... the supply of private cars falls in Germany</li>\n<li>D. allocative ...... more resources are allocated to the production of private cars in China</li>\n</ul>",
