   "text": "Study the following news extract.\n\n> In the last decade, the rent of residential units in Berlin was doubled due to continuous increase in demand. To deal with the problem, the Berlin government imposed a 'Rent Frozen Bill' under which the rent of residential units was not allowed to increase for at least 5 years.\n\nSuppose a similar bill is implemented in Hong Kong. Which of the following statements is correct?\n\n- A. The Gini coefficient will increase.\n- B. The property tax revenue of the government will increase.\n- C. There will be a deadweight loss if the demand for residential units keeps on increasing.\n- D. The property owners will have higher incentives to renovate their flats.",
   "html": "<p>19.&nbsp;&nbsp;&nbsp;Study the following news extract.</p>\n<blockquote>\n<p>In the last decade, the rent of residential units in Berlin was doubled due to continuous increase in demand. To deal with the problem, the Berlin government imposed a 'Rent Frozen Bill' under which the rent of residential units was not allowed to increase for at least 5 years.</p>\n</blockquote>\n<p>Suppose a similar bill is implemented in Hong Kong. Which of the following statements is correct?</p>\n<ul>\n<li>A. The Gini coefficient will increase.</li>\n<li>B. The property tax revenue of the government will increase.</li>\n<li>C. There will be a deadweight loss if the demand for residential units keeps on increasing.</li>\n<li>D. The property owners will have higher incentives to renovate their flats.</li>\n</ul>",
