   "text": "The following table shows the data of average annual income earned by women and men according to their age in 2018.\n\n| Age | Average annual income of women (HK$) | Average annual income of men (HK$) |\n|---|---|---|\n| 20 – 29 | 122000 | 121000 |\n| 50 – 59 | 482000 | 645000 |\n\nWhich of the following may explain the phenomena shown by the above data?\n(1) Women tend to leave the job market earlier than men for taking care of the family, leading to fewer women to take up senior positions in companies.\n(2) Sex discrimination in labour market exists in the older generations.\n(3) Accumulation of human capital contributes to the difference in income between different age groups.\n\n- A. (1) only\n- B. (2) only\n- C. (3) only\n- D. (1), (2) and (3)",
   "html": "<p>23.&nbsp;&nbsp;&nbsp;The following table shows the data of average annual income earned by women and men according to their age in 2018.</p>\n<table>\n<thead>\n<tr>\n<th>Age</th>\n<th>Average annual income of women (HK$)</th>\n<th>Average annual income of men (HK$)</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>20 – 29</td>\n<td>122000</td>\n<td>121000</td>\n</tr>\n<tr>\n<td>50 – 59</td>\n<td>482000</td>\n<td>645000</td>\n</tr>\n</tbody>\n</table>\n<p>Which of the following may explain the phenomena shown by the above data?\n(1) Women tend to leave the job market earlier than men for taking care of the family, leading to fewer women to take up senior positions in companies.\n(2) Sex discrimination in labour market exists in the older generations.\n(3) Accumulation of human capital contributes to the difference in income between different age groups.</p>\n<ul>\n<li>A. (1) only</li>\n<li>B. (2) only</li>\n<li>C. (3) only</li>\n<li>D. (1), (2) and (3)</li>\n</ul>",
