   "text": "Which of the following is a reason for a leftward shift of the short run aggregate supply curve in a country?\n\n- A. There is a continuous increase in price level.\n- B. The largest market of the country's exports suffers from an economic recession.\n- C. More citizens emigrate to foreign countries.\n- D. The wages of labour slowly adjust downward due to institutional factors.",
   "html": "<p>27.&nbsp;&nbsp;&nbsp;Which of the following is a reason for a leftward shift of the short run aggregate supply curve in a country?</p>\n<ul>\n<li>A. There is a continuous increase in price level.</li>\n<li>B. The largest market of the country's exports suffers from an economic recession.</li>\n<li>C. More citizens emigrate to foreign countries.</li>\n<li>D. The wages of labour slowly adjust downward due to institutional factors.</li>\n</ul>",
