   "text": "The following diagram shows the asset demand for money of an economy.\n\n![fig_2020P1_q28](2020_P1_images/fig_2020P1_q28.png)\n\nWhich of the following will cause the above change in asset demand for money?\n\n- A. The nominal interest rate increases.\n- B. There is a contraction of monetary base.\n- C. The use of electronic wallets such as Alipay（支付寶）becomes more popular.\n- D. The expected rate of return of holding bonds increases.",
   "html": "<p>28.&nbsp;&nbsp;&nbsp;The following diagram shows the asset demand for money of an economy.</p>\n<p><img alt=\"fig_2020P1_q28\" src=\"2020_P1_images/fig_2020P1_q28.png\" /></p>\n<p>Which of the following will cause the above change in asset demand for money?</p>\n<ul>\n<li>A. The nominal interest rate increases.</li>\n<li>B. There is a contraction of monetary base.</li>\n<li>C. The use of electronic wallets such as Alipay（支付寶）becomes more popular.</li>\n<li>D. The expected rate of return of holding bonds increases.</li>\n</ul>",
