   "text": "The diagram below shows the aggregate demand curve, the short run aggregate supply curve and the long run aggregate supply curve of an economy.\n\n![fig_2020P1_q36](2020_P1_images/fig_2020P1_q36.png)\n\nSuppose the economy initially operates at $E_0$ and the total import value equals to the total export value. If the government decreases the amount of social security assistance for the elderly, in the short run, the deflationary (output) gap will become \\_\\_\\_\\_\\_\\_ and there will be a \\_\\_\\_\\_\\_\\_.\n\n- A. narrower ...... trade surplus\n- B. narrower ...... trade deficit\n- C. wider ...... trade surplus\n- D. wider ...... trade deficit",
   "html": "<p>36.&nbsp;&nbsp;&nbsp;The diagram below shows the aggregate demand curve, the short run aggregate supply curve and the long run aggregate supply curve of an economy.</p>\n<p><img alt=\"fig_2020P1_q36\" src=\"2020_P1_images/fig_2020P1_q36.png\" /></p>\n<p>Suppose the economy initially operates at $E_0$ and the total import value equals to the total export value. If the government decreases the amount of social security assistance for the elderly, in the short run, the deflationary (output) gap will become ______ and there will be a ______.</p>\n<ul>\n<li>A. narrower ...... trade surplus</li>\n<li>B. narrower ...... trade deficit</li>\n<li>C. wider ...... trade surplus</li>\n<li>D. wider ...... trade deficit</li>\n</ul>",
