   "text": "In 2019, the Japanese government increases the general sales tax rate on most of the goods and services from 8% to 10%. As a result,\n(1) income inequality will be higher.\n(2) the fiscal deficit will be eliminated.\n(3) the invisible trade deficit will decrease.\n\n- A. (1) only\n- B. (2) only\n- C. (3) only\n- D. (1), (2) and (3)",
   "html": "<p>38.&nbsp;&nbsp;&nbsp;In 2019, the Japanese government increases the general sales tax rate on most of the goods and services from 8% to 10%. As a result,\n(1) income inequality will be higher.\n(2) the fiscal deficit will be eliminated.\n(3) the invisible trade deficit will decrease.</p>\n<ul>\n<li>A. (1) only</li>\n<li>B. (2) only</li>\n<li>C. (3) only</li>\n<li>D. (1), (2) and (3)</li>\n</ul>",
