   "text": "The following is an extract of the mission of the Inland Revenue Department.\n\n> Our Mission\n>\n> We are committed to\n>\n> - collecting revenue efficiently and cost-effectively\n> - enabling staff to acquire the necessary knowledge, skills and attitude so that they can contribute their best to the achievement of our vision\n\nThe above mission is in line with the \\_\\_\\_\\_\\_\\_ principle of taxation put forward by Adam Smith.\n\n- A. equality\n- B. certainty\n- C. convenience\n- D. economy",
   "html": "<p>39.&nbsp;&nbsp;&nbsp;The following is an extract of the mission of the Inland Revenue Department.</p>\n<blockquote>\n<p>Our Mission</p>\n<p>We are committed to</p>\n<ul>\n<li>collecting revenue efficiently and cost-effectively</li>\n<li>enabling staff to acquire the necessary knowledge, skills and attitude so that they can contribute their best to the achievement of our vision</li>\n</ul>\n</blockquote>\n<p>The above mission is in line with the ______ principle of taxation put forward by Adam Smith.</p>\n<ul>\n<li>A. equality</li>\n<li>B. certainty</li>\n<li>C. convenience</li>\n<li>D. economy</li>\n</ul>",
   "file": "2020_P1_QU(ENG).md"
