   "text": "Mr. Chan runs a factory in mainland China and earns a huge profit. Recently he has bought a flat and a second hand electric car in Hong Kong, and received dividends from his shares of HSBC.\n\nAccording to the above information, which type(s) of tax does he need to pay to the Hong Kong government?\n(1) Property tax\n(2) Stamp duty\n(3) Profits tax\n(4) First registration tax\n\n- A. (2) only\n- B. (1) and (4) only\n- C. (2) and (3) only\n- D. (1), (3) and (4) only",
   "html": "<p>40.&nbsp;&nbsp;&nbsp;Mr. Chan runs a factory in mainland China and earns a huge profit. Recently he has bought a flat and a second hand electric car in Hong Kong, and received dividends from his shares of HSBC.</p>\n<p>According to the above information, which type(s) of tax does he need to pay to the Hong Kong government?\n(1) Property tax\n(2) Stamp duty\n(3) Profits tax\n(4) First registration tax</p>\n<ul>\n<li>A. (2) only</li>\n<li>B. (1) and (4) only</li>\n<li>C. (2) and (3) only</li>\n<li>D. (1), (3) and (4) only</li>\n</ul>",
   "file": "2020_P1_QU(ENG).md"
