   "text": "The following table shows the change in the exchange rate of Euro against the US dollar.\n\n| Date | Exchange rate |\n|---|---|\n| 22 September 2018 | 1 EUR = US$ 1.176 |\n| 22 August 2019 | 1 EUR = US$ 1.109 |\n\nThe above change in the exchange rate will lead to a decrease in\n\n- A. the number of European tourists visiting the US.\n- B. the volume of goods exported from Europe to the US.\n- C. the total value of US exports to Europe (in terms of Euro).\n- D. the total value of European exports to the US (in term of the US dollar).",
   "html": "<p>44.&nbsp;&nbsp;&nbsp;The following table shows the change in the exchange rate of Euro against the US dollar.</p>\n<table>\n<thead>\n<tr>\n<th>Date</th>\n<th>Exchange rate</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>22 September 2018</td>\n<td>1 EUR = US$ 1.176</td>\n</tr>\n<tr>\n<td>22 August 2019</td>\n<td>1 EUR = US$ 1.109</td>\n</tr>\n</tbody>\n</table>\n<p>The above change in the exchange rate will lead to a decrease in</p>\n<ul>\n<li>A. the number of European tourists visiting the US.</li>\n<li>B. the volume of goods exported from Europe to the US.</li>\n<li>C. the total value of US exports to Europe (in terms of Euro).</li>\n<li>D. the total value of European exports to the US (in term of the US dollar).</li>\n</ul>",
   "file": "2020_P1_QU(ENG).md"
