   "html": "<p>45.&nbsp;&nbsp;&nbsp;Under the linked exchange rate system of Hong Kong, which of the following statements is correct?</p>\n<ul>\n<li>A. The money supply M1 of Hong Kong has to be fully backed up by the US dollar.</li>\n<li>B. Hong Kong's export volume will increase when the US dollar depreciates against other currencies.</li>\n<li>C. The market exchange rate of the HK dollar relative to the US dollar is fixed.</li>\n<li>D. Hong Kong citizens can sell 1 USD to the three note-issuing banks for 7.8 HKD.</li>\n</ul>",
